<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { watch } from 'vue';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { ApiExceptions } from 'src/exceptions/index';
import { useDropdownStore } from 'src/store/main';
import { date } from 'quasar';
import { useQuasar } from 'quasar';
import { reportApiService } from 'src/services';
import ApexCharts from 'apexcharts';
import type { dynamicObj } from 'src/pages/assets';
import { objLen } from 'src/utils/general';
import displayFieldLabel from 'src/utils/displayFieldLabel';
export default defineComponent({
  components: {},
  mixins: [displayFieldLabel],
  beforeRouteLeave: function (to: any, from: any, next: any) {
    next();
  },
  watch: {
    selected_date_range: {
      handler: function (newVal, oldVal) {
        this.selected_date_range_prev = oldVal;
      },
    },
  },
  data() {
    return {
      saved_requests: ref([] as any[]),
      fullWidthImageIndex: null,
      showBigImage: false,
      bigImage: '',
      chartData: ref([] as any),
      chart: ref(null as any),

      showParts: ref({} as dynamicObj),
      showSubDoctypesAverage: ref({} as dynamicObj),
      showSubDoctypesTotal: ref({} as dynamicObj),
      showOrgUserTimeAverage: ref({} as dynamicObj),
      showSubDoctypesStatus: ref({} as dynamicObj),
      showOrgTimeAverage: ref({} as dynamicObj),
      showExportUser: ref({} as dynamicObj),
      showExportOrg: ref({} as dynamicObj),
      showrejectstatus: false,
      showsonderwunschstatus: false,
    };
  },
  computed: {
    board_date: function () {
      if (this.selected_date_range === 'custom_reselect') {
        return this.custom_date_range.from + ' - ' + this.custom_date_range.to;
      }

      return this.selected_date_range;
    },
    selected_doc_type_label: function () {
      const doctypeInfo = this.getSelectedDocType();
      if (objLen(doctypeInfo) === 0) {
        return '';
      }

      return String(doctypeInfo.label);
    },
    average_time_spent: function () {
      let average_time_spent = 0;
      if (
        this.selected_doc_type === 'All' &&
        this.hasBoardInfo('average_time_spent')
      ) {
        average_time_spent = this.report_overall_stats.average_time_spent;
      }

      if (
        this.selected_doc_type !== 'All' &&
        this.hasDocBoardInfo('average_time_spent')
      ) {
        average_time_spent = this.report_document.average_time_spent;
      }

      return Math.round(average_time_spent);
    },
  },
  mounted() {
    this.initView();
    const $q = useQuasar();
    this.clearChart();
    watch(
      () => $q.dark.isActive,
      (val: any) => {
        this.clearChart();
        this.renderChart();
      },
    );
  },

  methods: {
    initView() {
      this.setDate();
      this.getReport();
    },
    prepareChartData() {
      let chart_data: any = [];
      this.changed_field_stats.forEach((item: dynamicObj) => {
        if (item.value == 1 || isNaN(item.value)) return;
        const chart_value = {
          x: this.getLabelForFormBuilder(item, '', true),
          y: item.value,
        };
        chart_data.push(chart_value);
      });
      if (chart_data.length > 15) {
        chart_data = chart_data.slice(0, 15);
      }
      this.chartData = chart_data;

       
      return chart_data;
    },
    clearChart() {
      var chart = document.getElementById('chart');
      if (chart) {
        chart.remove();
      }
      var chart_container = document.getElementById('chart-container');
      if (chart_container) {
        chart_container.innerHTML = '<div id="chart"></div>';
      }
    },
    renderChart() {
      const chart_data = this.prepareChartData();
      if (this.chartData.length == 0) {
        return;
      }
      var options = {
        chart: {
          type: 'bar',
          height: '400',
        },
        theme: {
          mode: this.$q.dark.isActive == true ? 'dark' : 'light',
          palette: 'palette1',
        },
        plotOptions: {
          bar: {
            horizontal: true,
          },
        },
        series: [
          {
            data: chart_data,
          },
        ],
      };

      if (document.querySelector('#chart') !== null) {
        this.chart = new ApexCharts(document.querySelector('#chart'), options);
        this.chart.render();
      }
    },
    setDate() {
      const numberOfDaysToAdd = Number(this.selected_date_range);
      const current_date = new Date();
      const end_date = new Date();
      const start = current_date.setDate(
        current_date.getDate() - numberOfDaysToAdd,
      );

      const startOfMonth = date.formatDate(start, 'YYYY/MM/DD');
      const endOfMonth = date.formatDate(end_date, 'YYYY/MM/DD');
      this.custom_date_range = { from: startOfMonth, to: endOfMonth };
      this.dropdown_store.custom_date_range = this.custom_date_range;
    },

    async getReport() {
      try {
        this.loading = true;
        this.dropdown_store.custom_date_range = this.custom_date_range;
        const data = Object.assign(
          {
            start_date: this.custom_date_range.from.replace(/\//g, '-'),
            end_date: this.custom_date_range.to.replace(/\//g, '-'),
          },
          this.getDocTypeParams(),
        );

        const response = await reportApiService.getReport(data);
        if (response.success === false) {
          throw response;
        }

        this.report_overall_stats = response.overall_stats;
        this.document_stats = response.document_stats;

        if (response.hasOwnProperty('document')) {
          this.report_document = response.document;
        }
        this.setChangedFieldStats();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async downloadReport() {
      try {
        this.loading = true;
        this.dropdown_store.custom_date_range = this.custom_date_range;
        const data = Object.assign(
          {
            start_date: this.custom_date_range.from.replace(/\//g, '-'),
            end_date: this.custom_date_range.to.replace(/\//g, '-'),
          },
          this.getDocTypeParams(),
        );

        const response = await reportApiService.getReportAsXLSX(data);

        const fileURL = window.URL.createObjectURL(new Blob([response.data]));
        const fileLink = document.createElement('a');
        fileLink.href = fileURL;
        fileLink.setAttribute('download', 'Report.xlsx');
        document.body.appendChild(fileLink);
        fileLink.click();
        fileLink.remove();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    getImageClass(i: any) {
      return {
        fullWidthImage: this.fullWidthImageIndex === i,
      };
    },

    onImageClick(i: any) {
      if (this.fullWidthImageIndex === i) {
        this.fullWidthImageIndex = null;
      } else {
        this.fullWidthImageIndex = i;
      }
    },

    flipShowParts(key: string, object: dynamicObj) {
      if (!object.hasOwnProperty(key)) {
        object[key] = true;
      } else {
        object[key] = object[key] ? false : true;
      }
    },

    showTheBigImage(request: any) {
      this.showBigImage = true;
      this.bigImage = request.image;
    },

    getDocTypeParams() {
      const data = {} as dynamicObj;

      if (this.selected_doc_type === 'All') {
        return data;
      }

      const doctypeInfo = this.getSelectedDocType();
      if (objLen(doctypeInfo) === 0) {
        return data;
      }

      data['doc_type'] = this.selected_doc_type;
      if (doctypeInfo.is_parent === false) {
        data['is_sub_doc_type'] = 'true';
      }

      return data;
    },

    getSelectedDocType() {
      const FILTERED = this.active_doc_types_sub_types_list.filter(
        (v: any) => v.value.indexOf(this.selected_doc_type) > -1,
      );

      if (FILTERED.length > 0) {
        return FILTERED[0] as dynamicObj;
      }

      return {} as dynamicObj;
    },

    setChangedFieldStats() {
      let fields = this.report_overall_stats.field_stats;
      if (this.selected_doc_type !== 'All') {
        fields = this.report_document.field_stats;
      }

      this.changed_field_stats = [];
      for (const [field_name, value] of Object.entries(fields)) {
        const field_stats = value as dynamicObj;
        const changed_count = field_stats.total - field_stats.correct;
        if (changed_count <= 0) {
          continue;
        }
        this.changed_field_stats.push({
          field_name: field_name,
          value: field_stats.total - field_stats.correct,
        });
      }
      this.changed_field_stats.sort((a, b) => (a.value < b.value ? 1 : -1));
      this.renderChart();
    },

    hasBoardInfo(key: string) {
      if (!this.report_overall_stats.hasOwnProperty(key)) {
        return false;
      }

      return true;
    },

    hasDocBoardInfo(key: string) {
      if (objLen(this.report_document) === 0) {
        return false;
      }

      if (!this.report_document.hasOwnProperty(key)) {
        return false;
      }

      return true;
    },

    docTypeSelected() {
      if (!this.selected_doc_type) {
        this.selected_doc_type = 'All';
      }
      this.getReport();
    },

    dateRangeCalenderSelected() {
      this.custom_range_selected = true;
      this.selected_date_range = 'custom_reselect';
      this.clearChart();
      this.getReport();
    },

    dateRangeOptionSelected() {
      if (this.selected_date_range === 'custom') {
        this.selected_date_range = this.selected_date_range_prev;
        this.show_calender = true;
        return;
      }

      this.setDate();
      this.clearChart();
      this.getReport();
    },

    showMoreBtnClicked() {
      setTimeout(() => {
        if (this.show_more_fields) {
          (this.$refs['more_fields'] as any).hide();
        } else {
          (this.$refs['more_fields'] as any).show();
        }
      }, 0);
    },

    showRejected(amount: number) {
      if (amount != 0) {
        this.showrejectstatus = true;
        return true;
      }
      return false;
    },

    showSonderwunsch(amount: number) {
      if (amount != 0) {
        this.showsonderwunschstatus = true;
        return true;
      }
      return false;
    },
  },

  setup() {
    const dropdown_store = useDropdownStore();
    const { active_doc_types_sub_types_list } = storeToRefs(dropdown_store);

    return {
      dropdown_store,
      active_doc_types_sub_types_list,
      selected_doc_type: ref('All'),
      selected_date_range: ref('30'),
      selected_date_range_prev: ref('30'),
      custom_date_range: ref({ from: '', to: '' }),
      report_overall_stats: ref({} as dynamicObj),
      document_stats: ref({} as dynamicObj),
      report_document: ref({} as dynamicObj),
      show_calender: ref(false),
      custom_range_selected: ref(false),
      loading: ref(false),
      changed_field_stats: ref([] as dynamicObj[]),
      show_more_fields: ref(false),
    };
  },
});
</script>

